window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-bb61e03460da1262"]={"versions": [{"id": "FIG-bb61e03460da1262", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-Tabellenmodells (OASIS Exchange Table Model) im Dokumentations-Subsystem des Generic Structure Template (M2-Metamodell). Das Diagramm definiert die statische strukturelle Zerlegung und Hierarchie tabellarischer Dokumentationsinhalte für Generatoren, Editoren und Dokumentations-Pipelines.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Metaklassen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>Table</code>: Hauptelement einer Tabelle, spezialisiert als <code>Paginateable</code>. Enthält:\n<ul class=\"fig-list\"><li><code>Caption</code> über gerichtete Komposition <code>+tableCaption</code> (Kardinalität <code>0..1</code>).\n</li><li><code>Tgroup</code> über gerichtete Komposition <code>+tgroup</code> (Kardinalität <code>1..*</code>, <code>{ordered}</code>).\n</li></ul>\n</li><li><code>Caption</code>: Beschriftung/Titel der Tabelle, abgeleitet von <code>MultilanguageReferrable</code>.\n</li><li><code>Tgroup</code>: Strukturelle Partition einer Tabelle. Enthält:\n<ul class=\"fig-list\"><li><code>Colspec</code> über gerichtete Komposition <code>+colspec</code> (Kardinalität <code>0..*</code>, <code>{ordered}</code>).\n</li><li><code>Tbody</code> als Tabellenkopf über gerichtete Komposition <code>+thead</code> (Kardinalität <code>0..1</code>).\n</li><li><code>Tbody</code> als Tabellenfuß über gerichtete Komposition <code>+tfoot</code> (Kardinalität <code>0..1</code>).\n</li><li><code>Tbody</code> als Tabellenkörper über gerichtete Komposition <code>+tbody</code> (Kardinalität <code>1</code>).\n</li></ul>\n</li><li><code>Colspec</code>: Spezifikation einzelner Spalteneigenschaften innerhalb der Partition.\n</li><li><code>Tbody</code>: Tabellenteil (Body, Thead oder Tfoot). Enthält:\n<ul class=\"fig-list\"><li><code>Row</code> über variabilitätsfähige gerichtete Komposition (<code>«atpVariation»</code>, Rolle <code>+row</code>, Kardinalität <code>1..*</code>, <code>{ordered}</code>).\n</li></ul>\n</li><li><code>Row</code>: Einzelne Tabellenzeile. Enthält:\n<ul class=\"fig-list\"><li><code>Entry</code> über gerichtete Komposition <code>+entry</code> (Kardinalität <code>1..*</code>, <code>{ordered}</code>).\n</li></ul>\n</li><li><code>Entry</code>: Tabellenzelle. Enthält:\n<ul class=\"fig-list\"><li><code>DocumentationBlock</code> (Stereotyp <code>«atpMixed»</code>) über gerichtete Komposition <code>+entryContents</code> (Kardinalität <code>1</code>).\n</li></ul>\n</li><li><code>DocumentationBlock</code>: Stereotypisiert mit <code>«atpMixed»</code>, kapselt die textuellen oder gemischten Dokumentationsinhalte einer Zelle.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Metamodell-Struktur ohne dynamische Ablauf- oder Verhaltenssequenzen. Die Auswertung erfolgt deklarativ über hierarchische Traversierung durch Generatoren oder Renderer: Auslesen der Metadaten und Caption auf Tabellenebene, Parsen der Spaltendefinitionen (<code>Colspec</code>) je Partition (<code>Tgroup</code>) sowie geordnete Instanziierung und Darstellung von Kopfzeilen (<code>thead</code>), Inhaltszeilen (<code>tbody</code>) und Fußzeilen (<code>tfoot</code>) mit zeilenweisem Durchlauf der einzelnen Zellen (<code>Entry</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Spezifikation der AUTOSAR-XML-Struktur für Tabellen im Austauschformat:</p>\n<ul class=\"fig-list\"><li>Vollständige Validierung der Kardinalitäten im Schema (XSD): Eine Tabelle erfordert mindestens eine <code>Tgroup</code>; jede <code>Tgroup</code> genau einen <code>tbody</code> sowie optional <code>thead</code> und <code>tfoot</code>.\n</li><li>Zeilen- und Spaltenstrukturen sind strikt geordnet (<code>{ordered}</code> an <code>+tgroup</code>, <code>+colspec</code>, <code>+row</code> und <code>+entry</code>).\n</li><li>Zeilen unterliegen der AUTOSAR-Variabilität (<code>«atpVariation»</code>), sodass zeilenbasierte Variantenbildung über Systemkonstanten und Vorbedingungen steuerbar ist.\n</li><li>Inhalte von <code>Entry</code> sind über <code>DocumentationBlock</code> typisiert und unterstützen gemischte Dokumentationsinhalte (<code>«atpMixed»</code>).\n</li><li><code>Table</code> implementiert <code>Paginateable</code>, wodurch Seitenumbrüche und Paginierungsverhalten steuerbar sind.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-b5a8b35fe306a9fe", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-Tabellenmodells (OASIS Exchange Table Model) im Dokumentations-Subsystem des Generic Structure Template (M2-Metamodell). Das Diagramm definiert die statische strukturelle Zerlegung und Hierarchie tabellarischer Dokumentationsinhalte für Generatoren, Editoren und Dokumentations-Pipelines.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Metaklassen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>Table</code>: Hauptelement einer Tabelle, spezialisiert als <code>Paginateable</code>. Enthält:\n<ul class=\"fig-list\"><li><code>Caption</code> über gerichtete Komposition <code>+tableCaption</code> (Kardinalität <code>0..1</code>).\n</li><li><code>Tgroup</code> über gerichtete Komposition <code>+tgroup</code> (Kardinalität <code>1..*</code>, <code>{ordered}</code>).\n</li></ul>\n</li><li><code>Caption</code>: Beschriftung/Titel der Tabelle, abgeleitet von <code>MultilanguageReferrable</code>.\n</li><li><code>Tgroup</code>: Strukturelle Partition einer Tabelle. Enthält:\n<ul class=\"fig-list\"><li><code>Colspec</code> über gerichtete Komposition <code>+colspec</code> (Kardinalität <code>0..*</code>, <code>{ordered}</code>).\n</li><li><code>Tbody</code> als Tabellenkopf über gerichtete Komposition <code>+thead</code> (Kardinalität <code>0..1</code>).\n</li><li><code>Tbody</code> als Tabellenfuß über gerichtete Komposition <code>+tfoot</code> (Kardinalität <code>0..1</code>).\n</li><li><code>Tbody</code> als Tabellenkörper über gerichtete Komposition <code>+tbody</code> (Kardinalität <code>1</code>).\n</li></ul>\n</li><li><code>Colspec</code>: Spezifikation einzelner Spalteneigenschaften innerhalb der Partition.\n</li><li><code>Tbody</code>: Tabellenteil (Body, Thead oder Tfoot). Enthält:\n<ul class=\"fig-list\"><li><code>Row</code> über variabilitätsfähige gerichtete Komposition (<code>«atpVariation»</code>, Rolle <code>+row</code>, Kardinalität <code>1..*</code>, <code>{ordered}</code>).\n</li></ul>\n</li><li><code>Row</code>: Einzelne Tabellenzeile, spezialisiert als <code>Paginateable</code>. Enthält:\n<ul class=\"fig-list\"><li><code>Entry</code> über gerichtete Komposition <code>+entry</code> (Kardinalität <code>1..*</code>, <code>{ordered}</code>).\n</li></ul>\n</li><li><code>Entry</code>: Tabellenzelle. Enthält:\n<ul class=\"fig-list\"><li><code>DocumentationBlock</code> (Stereotyp <code>«atpMixed»</code>) über gerichtete Komposition <code>+entryContents</code> (Kardinalität <code>1</code>).\n</li></ul>\n</li><li><code>DocumentationBlock</code>: Stereotypisiert mit <code>«atpMixed»</code>, kapselt die textuellen oder gemischten Dokumentationsinhalte einer Zelle.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Metamodell-Struktur ohne dynamische Ablauf- oder Verhaltenssequenzen. Die Auswertung erfolgt deklarativ über hierarchische Traversierung durch Generatoren oder Renderer: Auslesen der Metadaten und Caption auf Tabellenebene, Parsen der Spaltendefinitionen (<code>Colspec</code>) je Partition (<code>Tgroup</code>) sowie geordnete Instanziierung und Darstellung von Kopfzeilen (<code>thead</code>), Inhaltszeilen (<code>tbody</code>) und Fußzeilen (<code>tfoot</code>) mit zeilenweisem Durchlauf der einzelnen Zellen (<code>Entry</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Spezifikation der AUTOSAR-XML-Struktur für Tabellen im Austauschformat:</p>\n<ul class=\"fig-list\"><li>Vollständige Validierung der Kardinalitäten im Schema (XSD): Eine Tabelle erfordert mindestens eine <code>Tgroup</code>; jede <code>Tgroup</code> genau einen <code>tbody</code> sowie optional <code>thead</code> und <code>tfoot</code>.\n</li><li>Zeilen- und Spaltenstrukturen sind strikt geordnet (<code>{ordered}</code> an <code>+tgroup</code>, <code>+colspec</code>, <code>+row</code> und <code>+entry</code>).\n</li><li>Zeilen unterliegen der AUTOSAR-Variabilität (<code>«atpVariation»</code>), sodass zeilenbasierte Variantenbildung über Systemkonstanten und Vorbedingungen steuerbar ist.\n</li><li>Inhalte von <code>Entry</code> sind über <code>DocumentationBlock</code> typisiert und unterstützen gemischte Dokumentationsinhalte (<code>«atpMixed»</code>).\n</li><li>Sowohl <code>Table</code> als auch <code>Row</code> implementieren <code>Paginateable</code>, wodurch Seitenumbrüche und Paginierungseigenschaften sowohl auf Gesamttabellenebene als auch gezielt auf Zeilenebene gesteuert werden können.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-d7ec6ee2bcee726a", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-Tabellenmodells (OASIS Exchange Table Model) im Dokumentations-Subsystem des Generic Structure Template (M2-Metamodell). Das Diagramm definiert die statische strukturelle Zerlegung und Hierarchie tabellarischer Dokumentationsinhalte für Generatoren, Editoren und Dokumentations-Pipelines.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Metaklassen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>Table</code>: Hauptelement einer Tabelle, spezialisiert als <code>Paginateable</code>. Enthält:\n<ul class=\"fig-list\"><li><code>Caption</code> über gerichtete Komposition <code>+tableCaption</code> (Kardinalität <code>0..1</code>).\n</li><li><code>Tgroup</code> über gerichtete Komposition <code>+tgroup</code> (Kardinalität <code>1..*</code>, <code>{ordered}</code>).\n</li></ul>\n</li><li><code>Caption</code>: Beschriftung/Titel der Tabelle, abgeleitet von <code>MultilanguageReferrable</code>. Enthält:\n<ul class=\"fig-list\"><li><code>MultiLanguageOverviewParagraph</code> über gerichtete Komposition <code>+desc</code> (Kardinalität <code>0..1</code>).\n</li></ul>\n</li><li><code>MultiLanguageOverviewParagraph</code>: Mehrsprachiger Übersichtsparagraph/Beschreibungstext.\n</li><li><code>Tgroup</code>: Strukturelle Partition einer Tabelle. Enthält:\n<ul class=\"fig-list\"><li><code>Colspec</code> über gerichtete Komposition <code>+colspec</code> (Kardinalität <code>0..*</code>, <code>{ordered}</code>).\n</li><li><code>Tbody</code> als Tabellenkopf über gerichtete Komposition <code>+thead</code> (Kardinalität <code>0..1</code>).\n</li><li><code>Tbody</code> als Tabellenfuß über gerichtete Komposition <code>+tfoot</code> (Kardinalität <code>0..1</code>).\n</li><li><code>Tbody</code> als Tabellenkörper über gerichtete Komposition <code>+tbody</code> (Kardinalität <code>1</code>).\n</li></ul>\n</li><li><code>Colspec</code>: Spezifikation einzelner Spalteneigenschaften innerhalb der Partition.\n</li><li><code>Tbody</code>: Tabellenteil (Body, Thead oder Tfoot). Enthält:\n<ul class=\"fig-list\"><li><code>Row</code> über variabilitätsfähige gerichtete Komposition (<code>«atpVariation»</code>, Rolle <code>+row</code>, Kardinalität <code>1..*</code>, <code>{ordered}</code>).\n</li></ul>\n</li><li><code>Row</code>: Einzelne Tabellenzeile, spezialisiert als <code>Paginateable</code>. Enthält:\n<ul class=\"fig-list\"><li><code>Entry</code> über gerichtete Komposition <code>+entry</code> (Kardinalität <code>1..*</code>, <code>{ordered}</code>).\n</li></ul>\n</li><li><code>Entry</code>: Tabellenzelle. Enthält:\n<ul class=\"fig-list\"><li><code>DocumentationBlock</code> (Stereotyp <code>«atpMixed»</code>) über gerichtete Komposition <code>+entryContents</code> (Kardinalität <code>1</code>).\n</li></ul>\n</li><li><code>DocumentationBlock</code>: Stereotypisiert mit <code>«atpMixed»</code>, kapselt die textuellen oder gemischten Dokumentationsinhalte einer Zelle.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Metamodell-Struktur ohne dynamische Ablauf- oder Verhaltenssequenzen. Die Auswertung erfolgt deklarativ über hierarchische Traversierung durch Generatoren oder Renderer: Auslesen der Metadaten und Caption auf Tabellenebene, Parsen der Spaltendefinitionen (<code>Colspec</code>) je Partition (<code>Tgroup</code>) sowie geordnete Instanziierung und Darstellung von Kopfzeilen (<code>thead</code>), Inhaltszeilen (<code>tbody</code>) und Fußzeilen (<code>tfoot</code>) mit zeilenweisem Durchlauf der einzelnen Zellen (<code>Entry</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Spezifikation der AUTOSAR-XML-Struktur für Tabellen im Austauschformat:</p>\n<ul class=\"fig-list\"><li>Vollständige Validierung der Kardinalitäten im Schema (XSD): Eine Tabelle erfordert mindestens eine <code>Tgroup</code>; jede <code>Tgroup</code> genau einen <code>tbody</code> sowie optional <code>thead</code> und <code>tfoot</code>.\n</li><li><code>Caption</code> kann über <code>+desc</code> optional (<code>0..1</code>) einen mehrsprachigen beschreibenden Absatz (<code>MultiLanguageOverviewParagraph</code>) aufnehmen.\n</li><li>Zeilen- und Spaltenstrukturen sind strikt geordnet (<code>{ordered}</code> an <code>+tgroup</code>, <code>+colspec</code>, <code>+row</code> und <code>+entry</code>).\n</li><li>Zeilen unterliegen der AUTOSAR-Variabilität (<code>«atpVariation»</code>), sodass zeilenbasierte Variantenbildung über Systemkonstanten und Vorbedingungen steuerbar ist.\n</li><li>Inhalte von <code>Entry</code> sind über <code>DocumentationBlock</code> typisiert und unterstützen gemischte Dokumentationsinhalte (<code>«atpMixed»</code>).\n</li><li>Sowohl <code>Table</code> als auch <code>Row</code> implementieren <code>Paginateable</code>, wodurch Seitenumbrüche und Paginierungseigenschaften sowohl auf Gesamttabellenebene als auch gezielt auf Zeilenebene gesteuert werden können.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-ff0091ca551d5023", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-Tabellenmodells (OASIS Exchange Table Model) im Dokumentations-Subsystem des Generic Structure Template (M2-Metamodell). Das Diagramm definiert die statische strukturelle Zerlegung und Hierarchie tabellarischer Dokumentationsinhalte für Generatoren, Editoren und Dokumentations-Pipelines.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Metaklassen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>Table</code>: Hauptelement einer Tabelle, spezialisiert als <code>Paginateable</code>. Enthält:\n<ul class=\"fig-list\"><li><code>Caption</code> über gerichtete Komposition <code>+tableCaption</code> (Kardinalität <code>0..1</code>).\n</li><li><code>Tgroup</code> über gerichtete Komposition <code>+tgroup</code> (Kardinalität <code>1..*</code>, <code>{ordered}</code>).\n</li></ul>\n</li><li><code>Caption</code>: Beschriftung/Titel der Tabelle, abgeleitet von <code>MultilanguageReferrable</code>. Enthält:\n<ul class=\"fig-list\"><li><code>MultiLanguageOverviewParagraph</code> über gerichtete Komposition <code>+desc</code> (Kardinalität <code>0..1</code>).\n</li></ul>\n</li><li><code>MultiLanguageOverviewParagraph</code>: Mehrsprachiger Übersichtsparagraph/Beschreibungstext.\n</li><li><code>Tgroup</code>: Strukturelle Partition einer Tabelle. Enthält:\n<ul class=\"fig-list\"><li><code>Colspec</code> über gerichtete Komposition <code>+colspec</code> (Kardinalität <code>0..*</code>, <code>{ordered}</code>).\n</li><li><code>Tbody</code> als Tabellenkopf über gerichtete Komposition <code>+thead</code> (Kardinalität <code>0..1</code>).\n</li><li><code>Tbody</code> als Tabellenfuß über gerichtete Komposition <code>+tfoot</code> (Kardinalität <code>0..1</code>).\n</li><li><code>Tbody</code> als Tabellenkörper über gerichtete Komposition <code>+tbody</code> (Kardinalität <code>1</code>).\n</li></ul>\n</li><li><code>Colspec</code>: Spezifikation einzelner Spalteneigenschaften innerhalb der Partition.\n</li><li><code>Tbody</code>: Tabellenteil (Body, Thead oder Tfoot). Enthält:\n<ul class=\"fig-list\"><li><code>Row</code> über variabilitätsfähige gerichtete Komposition (<code>«atpVariation»</code>, Rolle <code>+row</code>, Kardinalität <code>1..*</code>, <code>{ordered}</code>).\n</li></ul>\n</li><li><code>Row</code>: Einzelne Tabellenzeile, spezialisiert als <code>Paginateable</code>. Enthält:\n<ul class=\"fig-list\"><li><code>Entry</code> über gerichtete Komposition <code>+entry</code> (Kardinalität <code>1..*</code>, <code>{ordered}</code>).\n</li></ul>\n</li><li><code>Entry</code>: Tabellenzelle. Enthält:\n<ul class=\"fig-list\"><li><code>DocumentationBlock</code> (Stereotyp <code>«atpMixed»</code>) über gerichtete Komposition <code>+entryContents</code> (Kardinalität <code>1</code>).\n</li></ul>\n</li><li><code>DocumentationBlock</code>: Stereotypisiert mit <code>«atpMixed»</code>, kapselt die textuellen oder gemischten Dokumentationsinhalte einer Zelle.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Metamodell-Struktur ohne dynamische Ablauf- oder Verhaltenssequenzen. Die Auswertung erfolgt deklarativ über hierarchische Traversierung durch Generatoren oder Renderer: Auslesen der Metadaten und Caption auf Tabellenebene, Parsen der Spaltendefinitionen (<code>Colspec</code>) je Partition (<code>Tgroup</code>) sowie geordnete Instanziierung und Darstellung von Kopfzeilen (<code>thead</code>), Inhaltszeilen (<code>tbody</code>) und Fußzeilen (<code>tfoot</code>) mit zeilenweisem Durchlauf der einzelnen Zellen (<code>Entry</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Spezifikation der AUTOSAR-XML-Struktur für Tabellen im Austauschformat:</p>\n<ul class=\"fig-list\"><li>Vollständige Validierung der Kardinalitäten im Schema (XSD): Eine Tabelle erfordert mindestens eine <code>Tgroup</code>; jede <code>Tgroup</code> genau einen <code>tbody</code> sowie optional <code>thead</code> und <code>tfoot</code>.\n</li><li><code>Caption</code> kann über <code>+desc</code> optional (<code>0..1</code>) einen mehrsprachigen beschreibenden Absatz (<code>MultiLanguageOverviewParagraph</code>) aufnehmen.\n</li><li>Zeilen- und Spaltenstrukturen sind strikt geordnet (<code>{ordered}</code> an <code>+tgroup</code>, <code>+colspec</code>, <code>+row</code> und <code>+entry</code>).\n</li><li>Zeilen unterliegen der AUTOSAR-Variabilität (<code>«atpVariation»</code>), sodass zeilenbasierte Variantenbildung über Systemkonstanten und Vorbedingungen steuerbar ist.\n</li><li>Inhalte von <code>Entry</code> sind über <code>DocumentationBlock</code> typisiert und unterstützen gemischte Dokumentationsinhalte (<code>«atpMixed»</code>).\n</li><li>Sowohl <code>Table</code> als auch <code>Row</code> implementieren <code>Paginateable</code>, wodurch Seitenumbrüche und Paginierungseigenschaften sowohl auf Gesamttabellenebene als auch gezielt auf Zeilenebene gesteuert werden können.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-bb61e03460da1262", "to": "FIG-b5a8b35fe306a9fe", "fr": "R4.0.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Metaklasse <code>Row</code>: Spezialisierung bzw. Eigenschaft <code>Paginateable</code> im Klassen-Header hinzugefügt.\n</li></ul>"}, {"from": "FIG-b5a8b35fe306a9fe", "to": "FIG-d7ec6ee2bcee726a", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Neue Metaklasse <code>MultiLanguageOverviewParagraph</code> hinzugefügt.\n</li><li>Metaklasse <code>Caption</code>: Neue Kompositionsbeziehung <code>+desc</code> mit Kardinalität <code>0..1</code> auf <code>MultiLanguageOverviewParagraph</code> ergänzt.\n</li></ul>"}, {"from": "FIG-d7ec6ee2bcee726a", "to": "FIG-ff0091ca551d5023", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
